  author, license, status
)
select id, upper(replace(id, '-', '_')), 'math', 10, topic, topic, prompt,
  option_a, option_b, option_c, option_d, correct_option, explanation,
  difficulty, 10, 'AI Mentor tự biên soạn theo chủ đề Toán 10',
  'AI Mentor', 'Nội bộ', 'PUBLISHED' from seed
on conflict (id) do nothing;

commit;
